<?php elseif($p==='companies'||$p==='agenda'):?><section class="card"><h2><?=h($p==='agenda'?'Contactos y próximas actuaciones':'Empresas vinculadas al grupo')?></h2><?php if(!$links)echo '<p>No hay empresas vinculadas.</p>';if($p==='agenda')uasort($links,fn($a,$b)=>strcmp($a['next']?:'9999',$b['next']?:'9999'));foreach($links as $id=>$l){$e=$l['snapshot']??$d['companies'][$id];echo '<details><summary>'.h($e['name'].' · '.$l['status'].' · '.$l['confirmed'].' plazas'.($l['next']?' · '.$l['next']:'')).'</summary><p>'.h($e['emails'].' · '.$e['phone']).'</p>';if($ed&&$p==='companies'){form_start('link',['c'=>$cid,'e'=>$id,'group'=>$gid]);select_field('status','Estado',array_combine($statuses,$statuses),$l['status']);input('requested','Solicitadas/ofrecidas',$l['requested'],'number');input('confirmed','Confirmadas',$l['confirmed'],'number');input('next','Próximo contacto',$l['next'],'date');area('notes','Observaciones',$l['notes']);end_form('Guardar seguimiento');}if($p==='agenda'){foreach(array_reverse($l['history']) as $hist)echo '<p class="event">'.h(($hist['at']??'').' · '.($hist['type']??'').' · '.($hist['note']??$hist['notes']??'')).'</p>';if($ed){form_start('history',['c'=>$cid,'e'=>$id]);select_field('type','Canal',array_combine($x=['Correo','Llamada','Visita','Reunión','Otro'],$x));area('note','Resultado');end_form('Registrar contacto');}}echo '</details>';}?></section>
